import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Layout from "./Layout";

function MyNotes({ search, setSearch }) {
  const [notes, setNotes] = useState([]);
  const [questions, setQuestions] = useState({});
  const [answers, setAnswers] = useState({});
  const [loading, setLoading] = useState(true);

  const user = JSON.parse(localStorage.getItem("user") || "null");
  const navigate = useNavigate();

  // ===============================
  // LOAD MY NOTES
  // ===============================
  const loadNotes = async () => {
    try {
      const res = await fetch("http://localhost:5000/api/notes");
      const data = await res.json();

      const myNotes = data.filter(
        (note) => note.uploadedBy === user?.name
      );

      setNotes(myNotes);

      // Load questions for every note
      for (const note of myNotes) {
        loadQuestions(note._id);
      }

      setLoading(false);
    } catch (err) {
      console.log(err);
      setLoading(false);
    }
  };

  // ===============================
  // LOAD QUESTIONS FOR NOTE
  // ===============================
  const loadQuestions = async (noteId) => {
    try {
      const res = await fetch(
        `http://localhost:5000/api/notes/${noteId}/questions`
      );

      const data = await res.json();

      setQuestions((prev) => ({
        ...prev,
        [noteId]: data,
      }));
    } catch (err) {
      console.log(err);
    }
  };

  useEffect(() => {
    if (!user) {
      navigate("/login");
      return;
    }

    loadNotes();
  }, []);

  // ===============================
  // ANSWER QUESTION
  // ===============================
  const handleAnswer = async (questionId, noteId) => {
    const answer = answers[questionId];

    if (!answer?.trim()) {
      alert("Please write an answer first");
      return;
    }

    try {
      const res = await fetch(
        `http://localhost:5000/api/answer/${questionId}`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            answer,
            answeredBy: user?.name,
          }),
        }
      );

      const data = await res.json();

      if (res.ok) {
        alert("Answer submitted successfully! ✅");

        setAnswers((prev) => ({
          ...prev,
          [questionId]: "",
        }));

        // Reload questions for this note
        loadQuestions(noteId);
      } else {
        alert(data.message || "Failed to answer");
      }
    } catch (err) {
      console.log(err);
      alert("Server error");
    }
  };

  // ===============================
  // SEARCH
  // ===============================
  const filtered = notes.filter((note) => {
    const s = search?.toLowerCase() || "";

    return (
      note.title?.toLowerCase().includes(s) ||
      note.topic?.toLowerCase().includes(s)
    );
  });

  return (
    <Layout search={search} setSearch={setSearch}>

      <div style={{ maxWidth: "900px", margin: "0 auto" }}>

        {/* HEADER */}
        <div className="header">

          <div>
            <h2>📚 My Notes</h2>

            <p>
              {filtered.length} notes uploaded
            </p>
          </div>

          <button
            className="new-post"
            onClick={() => navigate("/upload")}
          >
            + Upload Note
          </button>

        </div>


        {/* LOADING */}
        {loading && <p>Loading your notes...</p>}


        {/* EMPTY */}
        {!loading && filtered.length === 0 && (

          <div
            className="card"
            style={{
              textAlign: "center",
              padding: "45px",
            }}
          >

            <div style={{ fontSize: "50px" }}>
              📚
            </div>

            <h3>No notes uploaded yet</h3>

            <p style={{ color: "#888" }}>
              Upload notes and help your juniors!
            </p>

            <button
              className="btn"
              style={{ maxWidth: "220px" }}
              onClick={() => navigate("/upload")}
            >
              + Upload Note
            </button>

          </div>
        )}


        {/* NOTES */}
        {filtered.map((note) => {

          const noteQuestions = questions[note._id] || [];

          return (

            <div
              key={note._id}
              className="post"
              style={{ marginBottom: "20px" }}
            >

              {/* ================= NOTE HEADER ================= */}

              <div className="post-top">

                <div className="user">

                  <div className="avatar small">
                    {user?.name?.[0]?.toUpperCase()}
                  </div>

                  <div>
                    <b>{note.uploadedBy}</b>

                    <p
                      style={{
                        margin: 0,
                        fontSize: "12px",
                      }}
                    >
                      {user?.role}
                    </p>
                  </div>

                </div>

                <span className="tag">
                  {note.topic}
                </span>

              </div>


              {/* NOTE TITLE */}

              <h3>
                📄 {note.title}
              </h3>


              {/* DOWNLOAD */}

              <div className="post-bottom">

                <a
                  href={`http://localhost:5000/uploads/${note.file}`}
                  target="_blank"
                  rel="noreferrer"
                  className="view-btn"
                >
                  📥 Download Note
                </a>

                <span>
                  💬 {noteQuestions.length} Questions
                </span>

              </div>


              {/* ================= QUESTIONS ================= */}

              <div
                style={{
                  marginTop: "20px",
                  paddingTop: "18px",
                  borderTop: "1px solid #edf1ee",
                }}
              >

                <h4
                  style={{
                    margin: "0 0 14px",
                    color: "#26352c",
                  }}
                >
                  💬 Questions from Students
                </h4>


                {noteQuestions.length === 0 ? (

                  <p
                    style={{
                      color: "#999",
                      fontSize: "14px",
                    }}
                  >
                    No questions about this note yet.
                  </p>

                ) : (

                  noteQuestions.map((question) => (

                    <div
                      key={question._id}
                      style={{
                        background: "#f7faf8",
                        border: "1px solid #e3ebe6",
                        borderRadius: "10px",
                        padding: "15px",
                        marginBottom: "12px",
                      }}
                    >

                      {/* STUDENT */}

                      <div
                        style={{
                          display: "flex",
                          alignItems: "center",
                          gap: "9px",
                          marginBottom: "9px",
                        }}
                      >

                        <div className="avatar small">
                          {question.postedBy?.[0]?.toUpperCase() || "U"}
                        </div>

                        <div>

                          <b style={{ fontSize: "13px" }}>
                            {question.postedBy}
                          </b>

                          <p
                            style={{
                              margin: 0,
                              fontSize: "11px",
                              color: "#888",
                            }}
                          >
                            {question.role}
                          </p>

                        </div>

                      </div>


                      {/* QUESTION */}

                      <p
                        style={{
                          margin: "8px 0 12px",
                          fontWeight: "600",
                          color: "#37423b",
                        }}
                      >
                        ❓ {question.title}
                      </p>


                      {/* ALREADY ANSWERED */}

                      {question.answer ? (

                        <div
                          style={{
                            background: "#eaf7ee",
                            padding: "12px",
                            borderRadius: "8px",
                          }}
                        >

                          <p
                            style={{
                              margin: "0 0 5px",
                              color: "#315f3e",
                            }}
                          >
                            <b>Your Answer:</b>
                          </p>

                          <p style={{ margin: 0 }}>
                            {question.answer}
                          </p>

                          <small style={{ color: "#777" }}>
                            Answered by {question.answeredBy}
                          </small>

                        </div>

                      ) : (

                        /* ================= ANSWER ================= */

                        <div>

                          <textarea
                            placeholder="Write your answer..."
                            value={answers[question._id] || ""}
                            onChange={(e) =>
                              setAnswers((prev) => ({
                                ...prev,
                                [question._id]: e.target.value,
                              }))
                            }
                            style={{
                              width: "100%",
                              minHeight: "80px",
                              padding: "10px",
                              borderRadius: "8px",
                              border: "1px solid #dbe4de",
                              resize: "vertical",
                            }}
                          />

                          <button
                            className="btn"
                            style={{
                              width: "auto",
                              padding: "9px 18px",
                              marginTop: "8px",
                            }}
                            onClick={() =>
                              handleAnswer(
                                question._id,
                                note._id
                              )
                            }
                          >
                            Submit Answer
                          </button>

                        </div>

                      )}

                    </div>

                  ))

                )}

              </div>

            </div>

          );
        })}

      </div>

    </Layout>
  );
}

